def longest_common_suffix(strs):
    if not strs:
        return ""
    suffix = strs[0]
    for s in strs[1:]:
        while not s.endswith(suffix):
            suffix = suffix[1:]
            if not suffix:
                return ""
    return suffix

def is_subsequence(s1, s2):
    it = iter(s2)
    return all(ch in it for ch in s1)

def interleave_strings(s1, s2):
    out = []
    i = 0
    n = max(len(s1), len(s2))
    for i in range(n):
        if i < len(s1):
            out.append(s1[i])
        if i < len(s2):
            out.append(s2[i])
    return ''.join(out)

def reverse_digits_in_string(s):
    digits = [ch for ch in s if ch.isdigit()][::-1]
    out = []
    idx = 0
    for ch in s:
        if ch.isdigit():
            out.append(digits[idx])
            idx += 1
        else:
            out.append(ch)
    return ''.join(out)

def matches_wildcard(s, pattern):
    m, n = len(s), len(pattern)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for j in range(1, n + 1):
        if pattern[j-1] == '*':
            dp[0][j] = dp[0][j-1]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[j-1] == '*':
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
            elif pattern[j-1] == '?' or s[i-1] == pattern[j-1]:
                dp[i][j] = dp[i-1][j-1]
    return dp[m][n]

def remove_repeated_words(s):
    words = s.split()
    out = []
    for w in words:
        if not out or out[-1] != w:
            out.append(w)
    return ' '.join(out)

def find_all_occurrences(s, sub):
    if sub == "":
        return []
    out = []
    start = 0
    while True:
        idx = s.find(sub, start)
        if idx == -1:
            break
        out.append(idx)
        start = idx + 1
    return out

def is_isomorphic(s1, s2):
    if len(s1) != len(s2):
        return False
    map12 = {}
    map21 = {}
    for a, b in zip(s1, s2):
        if a in map12 and map12[a] != b:
            return False
        if b in map21 and map21[b] != a:
            return False
        map12[a] = b
        map21[b] = a
    return True

def count_case_transitions(s):
    count = 0
    for a, b in zip(s, s[1:]):
        if a.isalpha() and b.isalpha():
            if (a.isupper() and b.islower()) or (a.islower() and b.isupper()):
                count += 1
    return count

def leetspeak(s):
    mapping = {'a': '4', 'e': '3', 'i': '1', 'o': '0', 's': '5', 't': '7'}
    out = []
    for ch in s:
        low = ch.lower()
        out.append(mapping[low] if low in mapping else ch)
    return ''.join(out)

def count_palindrome_words(s):
    count = 0
    for w in s.split():
        lw = w.lower()
        if lw == lw[::-1]:
            count += 1
    return count

def find_anagram_matches(words, target):
    key = sorted(target.lower())
    return [w for w in words if sorted(w.lower()) == key]

def zigzag_convert(s, num_rows):
    if num_rows <= 1 or num_rows >= len(s):
        return s
    rows = [''] * num_rows
    cur = 0
    step = 1
    for ch in s:
        rows[cur] += ch
        if cur == 0:
            step = 1
        elif cur == num_rows - 1:
            step = -1
        cur += step
    return ''.join(rows)

def min_case_changes_alternating(s):
    letters = [ch for ch in s if ch.isalpha()]
    if not letters:
        return 0
    cost_upper_start = 0
    cost_lower_start = 0
    for i, ch in enumerate(letters):
        want_upper = (i % 2 == 0)
        is_upper = ch.isupper()
        if want_upper != is_upper:
            cost_upper_start += 1
        else:
            cost_lower_start += 1
    return min(cost_upper_start, cost_lower_start)
